    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        k = parts[0]
        literals = parts[1:]
        # A clause (l1 ∨ l2 ∨ ... ∨ lk) is equivalent to
        # (¬l1 → l2) ∧ (¬l2 → l3) ∧ ... ∧ (¬l(k-1) → lk)
        # AND (¬li → lj) for any i ≠ j

        for j in range(k):
