    # Actually, let's use a cleaner implementation
    adj_rev = [[] for _ in range(2 * m + 1)]

    # Build both forward and reverse graphs
    for u in range(1, 2 * m + 1):
        for v in adj[u]:
            adj_rev[v].append(u)

    visited = [False] * (2 * m + 1)
    topo_order = []

    # First DFS on forward graph to get finishing order
    def dfs_first(node):
        visited[node] = True
        for neighbor in adj[node]:
            if not visited[neighbor]:
                dfs_first(neighbor)
        topo_order.append(node)

    for i in range(1, 2 * m + 1):
        if not visited[i]:
            dfs_first(i)

    # Second DFS on reverse graph in reverse topological order
    visited = [False] * (2 * m + 1)
    scc_id = [-1] * (2 * m + 1)
    scc_counter = 0

    def dfs_second(node, scc):
        visited[node] = True
        scc_id[node] = scc_counter
        for neighbor in adj_rev[node]:
