    for i in range(m):
        parts = list(map(int, lines[2 + i].split()))
        u, v, w = parts[0], parts[1], parts[2]
        edges.append((u, v, w, i))

    def build_adj(edges, blacklist):
        """Build adjacency list from edges, excluding blacklisted edges"""
        adj = [[] for _ in range(n + 1)]
        for i, (u, v, w, _) in enumerate(edges):
            if i not in blacklist:
                adj[u].append(v)
                adj[v].append(u)
        return adj

    def is_connected(start, end, adj):
        """Check if there's a path from start to end using BFS"""
        if start == end:
            return True
        visited = [False] * (n + 1)
        queue = deque([start])
        visited[start] = True

        while queue:
            curr = queue.popleft()
            if curr == end:
                return True
            for neighbor in adj[curr]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)
        return False

    # Check if already disconnected (cost 0)
    adj = build_adj(edges, set())
    if not is_connected(s, t, adj):
        return '0\n0\n'

    best_cost = float('inf')
    best_edges = None

    # Try removing 1 edge
    for i, (u, v, w, _) in enumerate(edges):
        adj = build_adj(edges, {i})
        if not is_connected(s, t, adj):
            if w < best_cost:
                best_cost = w
                best_edges = (i, 1)

    # Try removing 2 edges if 1 edge is not enough
    if best_edges is None:
        for i, (u, v, w1, _) in enumerate(edges):
            for j, (a, b, w2, _) in enumerate(edges):
                if i < j:
                    adj = build_adj(edges, {i, j})
                    if not is_connected(s, t, adj):
                        if w1 + w2 < best_cost:
                            best_cost = w1 + w2
                            best_edges = (i, j, 2)

    if best_edges is None:
        import sys
        sys.stdout.write('-1\n')
        return

    edges_needed = []
    if best_edges[1] == 1:
        edges_needed.append(str(best_edges[0] + 1))  # Convert 0-index to 1-index
    else:
