def is_stable(match, cost):
    n = len(match)
    for i in range(n):
        j = match[i]
        for k in range(n):
            if k == j or match[k] == j:
                continue
            cost_ik = cost[i][k]
            cost_ij = cost[i][j]
            cost_ki = cost[k][i]
            cost_kj = cost[k][match[k]]
            if cost_ik < cost_ij and cost_ki < cost_kj:
                return False
    return True

