    if sqrt_r >= 0:
        is_prime_small[0] = False
    if sqrt_r >= 1:
        is_prime_small[1] = False

    base_primes = []
    for i in range(2, sqrt_r + 1):
        if is_prime_small[i]:
            base_primes.append(i)
            for j in range(i * i, sqrt_r + 1, i):
                is_prime_small[j] = False

    # Segmented sieve for [l, r]
    segment_len = r - l + 1
    is_prime_seg = [True] * segment_len

    # For each small prime, mark its multiples in the segment
    for p in base_primes:
        # Start from first multiple of p >= l and >= p*p
        start = max(p * p, ((l + p - 1) // p) * p)
        for num in range(start, r + 1, p):
            is_prime_seg[num - l] = False

    # Count primes that are either 2 or ≡ 1 (mod 4)
    count = 0
    for i in range(segment_len):
        num = l + i
        if is_prime_seg[i] and (num == 2 or num % 4 == 1):
            count += 1

    return f"{count}\n"

