MOD = 998244353

def power(a: int, b: int, m: int = MOD) -> int:
    result = 1
    a %= m
    while b > 0:
        if b % 2 == 1:
            result = result * a % m
        a = a * a % m
        b //= 2
    return result

def modInverse(n: int) -> int:
    return power(n, MOD - 2, MOD)

