    precompute_factorials = lambda limit: (
        [1] * (limit + 1),
        [1] * (limit + 1),
        lambda n, k: (fac[n] * invfac[k] % MOD * invfac[n - k] % MOD) if 0 <= k <= n else 0
    )

    fac, invfac, binom = precompute_factorials(n + 10)

    # Precompute powers of 2
    two_pow = [1] * (2 * n + 1)
    for i in range(1, 2 * n + 1):
        two_pow[i] = two_pow[i - 1] * 2 % MOD

    # Precompute inverse of odd denominators
    inv_denom = {}
    for t in range(1, 2 * n + 3):
        if t % 2 == 1:
            inv_denom[t] = modInverse(t)

    # Compute M[t] = integral_0^1 p(x)^t dx where p(x) = 2x(1-x)
    M = [0] * (2 * n + 1)
    for t in range(1, 2 * n + 1):
        total = 0
        for m in range(t + 1):
            c = binom(t, m)
            d = 2 * t - m + 1
            sign = -1 if (t - m) % 2 == 1 else 1
            term = c * inv_denom[d] % MOD
            if sign == 1:
                total = (total + term) % MOD
            else:
                total = (total - term + MOD) % MOD
        M[t] = two_pow[t] * total % MOD

    # Compute answer = l * sum_{j=k}^n C(n,j) * integral_{0}^1 p(x)^j (1-p(x))^{n-j} dx
    # Expand (1-p)^{n-j} = sum C(n-j,i) (-1)^i p^i
    # Contribution = sum_{j=k}^n C(n,j) * sum_{i=0}^{n-j} C(n-j,i) (-1)^i * M[j+i]

    result = 0
