# Solution for calculating f_r(n) modulo 10^9 + 7

def solution(input_str):
    MAX = 1000000 + 5
    MOD = 1000000007

    # Precompute SPF using sieve
    spf = list(range(MAX))
    for i in range(2, int(MAX**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, MAX, i):
                if spf[j] == j:
                    spf[j] = i

    # Precompute factorials and inverse factorials
    fact = [1] * MAX
    inv = [1] * MAX

    for i in range(1, MAX):
        fact[i] = (fact[i-1] * i) % MOD

    if MOD - 1 % 2 == 1:
        inv[MAX-1] = pow(fact[MAX-1], MOD-2, MOD)
        for i in range(MAX-2, -1, -1):
            inv[i] = (inv[i+1] * (i+1)) % MOD

    def nCr_mod(n, r):
        if r < 0 or r > n:
            return 0
        numerator = fact[n]
        denominator = inv[r] * inv[n-r] % MOD
        return numerator * denominator % MOD

    def query(r, n):
        if n == 1:
            return 1

        result = 1
        temp = n

        while temp > 1:
            p = spf[temp]
            exp = 0

            while temp % p == 0:
                temp //= p
                exp += 1

            # Compute: C(exp+r, r) + C(exp+r-1, r)
            term1 = nCr_mod(exp+r, r)
            term2 = nCr_mod(exp+r-1, r)
            term = (term1 + term2) % MOD

            result = (result * term) % MOD

        return result

    lines = input_str.strip().split('\n')
    q = int(lines[0])

    answers = []
    for i in range(1, q + 1):
        parts = lines[i].split()
        r = int(parts[0])
        n = int(parts[1])
        answers.append(str(query(r, n)))

    return '\n'.join(answers)

