def is_canonical(s):
    # Generate all 4 transforms
    transforms = [s, s[::-1]]  # reverse
    def flip(t):
        return ''.join(['1' if c == '0' else '0' for c in t])

    for t in s, s[::-1]:
        transforms.append(t)
        transforms.append(flip(t))

